import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.Cs5aHXsR.js";var i=JSON.parse(`{"title":"FAQ and troubleshooting","description":"","frontmatter":{},"headers":[],"relativePath":"guide/faq.md","filePath":"guide/faq.md","lastUpdated":1787913597000}`),a={name:`guide/faq.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="faq-and-troubleshooting" tabindex="-1">FAQ and troubleshooting <a class="header-anchor" href="#faq-and-troubleshooting" aria-label="Permalink to “FAQ and troubleshooting”">​</a></h1><h2 id="one-tool-i-expected-is-missing" tabindex="-1">One tool I expected is missing <a class="header-anchor" href="#one-tool-i-expected-is-missing" aria-label="Permalink to “One tool I expected is missing”">​</a></h2><p>Almost always the tool filter rather than a bug. Check <code>GSC_ALLOW_TOOLS</code>, <code>GSC_DENY_TOOLS</code> and <code>GSC_READ_ONLY</code> — a filtered tool is removed outright, so a call to it answers exactly as an unknown name would, which is indistinguishable from &quot;this server never had it&quot;.</p><p><code>GSC_READ_ONLY=true</code> removes all nine write tools. <code>GSC_ALLOW_TOOLS=essential</code> leaves only five.</p><p>See <a href="/guide/configuration#choosing-the-tools-that-load">choosing the tools that load</a>.</p><p>The other possibility is that Google has no such method. <code>mobileFriendlyTest</code> is the one people look for: it is still in Google&#39;s discovery document and the service behind it was switched off in December 2023, so a tool for it could only ever return an error.</p><h2 id="everything-returns-403-and-the-credential-is-right" tabindex="-1">Everything returns 403 and the credential is right <a class="header-anchor" href="#everything-returns-403-and-the-credential-is-right" aria-label="Permalink to “Everything returns 403 and the credential is right”">​</a></h2><p>403 covers four unrelated causes here, and the reason is in the error body rather than the status. The server reads it and says which:</p><ul><li><strong>The API is not enabled</strong> in the Cloud project. Search Console, Site Verification and Indexing are three separate switches. This is the most common first failure and the one that reads least like itself — &quot;permission denied&quot; sends people to Search Console&#39;s user list when the problem is a Cloud project they did not know they had.</li><li><strong>The identity has no access to the property.</strong> <code>list_sites</code> shows exactly which properties it can see; an empty list means none, which is the normal state of a fresh service account.</li><li><strong>The token lacks the scope.</strong> For an OAuth refresh token the scopes were fixed at consent and it has to be re-issued.</li><li><strong>The Indexing API wants ownership</strong>, not user access. Full user is not enough.</li></ul><h2 id="a-property-i-can-see-in-the-web-interface-answers-404" tabindex="-1">A property I can see in the web interface answers 404 <a class="header-anchor" href="#a-property-i-can-see-in-the-web-interface-answers-404" aria-label="Permalink to “A property I can see in the web interface answers 404”">​</a></h2><p>The spelling is exact and there are two kinds:</p><ul><li><code>sc-domain:example.com</code> — a domain property</li><li><code>https://example.com/</code> — a URL-prefix property, <strong>trailing slash required</strong></li></ul><p>They are different properties with different data. <code>https://example.com</code> without the slash is not a lenient spelling of the second one; it is nothing, and Google answers 403. This server adds the slash for you, and refuses a bare <code>example.com</code> rather than guessing which of the two you meant.</p><p><code>list_sites</code> shows the spellings your credential can actually use.</p><h2 id="the-property-exists-but-every-data-call-fails" tabindex="-1">The property exists but every data call fails <a class="header-anchor" href="#the-property-exists-but-every-data-call-fails" aria-label="Permalink to “The property exists but every data call fails”">​</a></h2><p>Look at its <code>permissionLevel</code>. If it says <code>siteUnverifiedUser</code>, the property was added without ownership ever being proven — which <code>sites.add</code> allows, silently.</p><p><code>setup_site</code> reports this and hands over the verification token to place.</p><h2 id="an-analytics-query-returns-nothing" tabindex="-1">An analytics query returns nothing <a class="header-anchor" href="#an-analytics-query-returns-nothing" aria-label="Permalink to “An analytics query returns nothing”">​</a></h2><p>Three usual causes, in order of likelihood:</p><ol><li><strong>The range is too recent.</strong> Data is finalised two to three days behind. The default <code>dataState: &quot;FINAL&quot;</code> omits the incomplete days; <code>&quot;ALL&quot;</code> includes them.</li><li><strong>The <code>hour</code> dimension without <code>dataState: &quot;HOURLY_ALL&quot;</code>.</strong> Google returns an empty result and no error for that combination — indistinguishable from a property with no traffic. This server refuses it up front instead.</li><li><strong>The property genuinely has no impressions</strong> for that range and filter.</li></ol><h2 id="the-totals-do-not-match-search-console-s-interface" tabindex="-1">The totals do not match Search Console&#39;s interface <a class="header-anchor" href="#the-totals-do-not-match-search-console-s-interface" aria-label="Permalink to “The totals do not match Search Console&#39;s interface”">​</a></h2><p>If the query includes the <code>query</code> dimension, they will not, and neither is wrong. Google withholds queries too rare to be anonymous, and the omitted rows still happened — commonly a third or more of all impressions. Every totals line this server prints says so.</p><p>Query <em>without</em> the query dimension for a true property total.</p><h2 id="why-is-the-average-position-different-from-what-i-calculated" tabindex="-1">Why is the average position different from what I calculated? <a class="header-anchor" href="#why-is-the-average-position-different-from-what-i-calculated" aria-label="Permalink to “Why is the average position different from what I calculated?”">​</a></h2><p>Because it is weighted by impressions, and an unweighted average of the position column is not a meaningful number. A thousand rare queries ranking 80th would drag a property whose real average is 12 up into the nineties.</p><p>CTR is computed the same way, from total clicks over total impressions rather than by averaging the row CTRs.</p><h2 id="request-indexing-said-it-worked-and-nothing-happened" tabindex="-1"><code>request_indexing</code> said it worked and nothing happened <a class="header-anchor" href="#request-indexing-said-it-worked-and-nothing-happened" aria-label="Permalink to “request_indexing said it worked and nothing happened”">​</a></h2><p>That is the documented behaviour. The Indexing API accepts a notification for any URL the credential owns and only <em>acts</em> on pages carrying JobPosting or BroadcastEvent structured data. For anything else it returns 200 with a timestamp and does nothing.</p><p>There is no API that makes Google crawl an ordinary page sooner. Submit a sitemap and wait.</p><h2 id="how-do-i-refresh-a-sitemap-google-already-has" tabindex="-1">How do I refresh a sitemap Google already has? <a class="header-anchor" href="#how-do-i-refresh-a-sitemap-google-already-has" aria-label="Permalink to “How do I refresh a sitemap Google already has?”">​</a></h2><p>Submit the same URL again — <code>submit_sitemap</code> is a <code>PUT</code> of an address, so submitting is updating. There is no separate update call, and the <code>google.com/ping?sitemap=</code> endpoint that used to nudge Google along was removed in June 2023 with no replacement.</p><p>Google re-fetches on its own schedule; nothing can force it.</p><h2 id="verify-site-fails-right-after-i-created-the-dns-record" tabindex="-1"><code>verify_site</code> fails right after I created the DNS record <a class="header-anchor" href="#verify-site-fails-right-after-i-created-the-dns-record" aria-label="Permalink to “verify_site fails right after I created the DNS record”">​</a></h2><p>Expected, and worth one retry later. DNS records take minutes to an hour to propagate, and a freshly uploaded verification file may still be behind a CDN cache. A failure here is almost always &quot;not there yet&quot; rather than &quot;wrong&quot;.</p><h2 id="can-i-use-this-against-a-property-behind-a-google-workspace-policy" tabindex="-1">Can I use this against a property behind a Google Workspace policy? <a class="header-anchor" href="#can-i-use-this-against-a-property-behind-a-google-workspace-policy" aria-label="Permalink to “Can I use this against a property behind a Google Workspace policy?”">​</a></h2><p>Yes, with a service account under domain-wide delegation — and that is exactly why the requested scopes follow the registered tools. A Workspace administrator allowlists specific scopes, and asking for one that was not delegated fails the whole token request. Narrow the tool list to what you were granted.</p>`,36)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};